import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_depth,
    int input_width,
    int input_height,
    int output_depth,
    int output_width,
    int output_height,
    int kernel_depth,
    int kernel_width,
    int kernel_height,
    int stride_d,
    int stride_w,
    int stride_h,
    int pad_d,
    int pad_w,
    int pad_h,
    int dilation_d,
    int dilation_w,
    int dilation_h,
    int groups
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_d_idx = blockIdx.z;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_d_idx >= output_depth) return;

    int group_size = out_channels / groups;
    int group_idx = out_ch_idx / group_size;

    // Each thread handles one output element
    int out_w_idx = threadIdx.x;
    int out_h_idx = threadIdx.y;

    if (out_w_idx >= output_width || out_h_idx >= output_height) return;

    // Calculate output coordinates
    int out_d = out_d_idx;
    int out_w = out_w_idx;
    int out_h = out_h_idx;

    // Calculate input coordinates
    int in_d_start = out_d * stride_d - pad_d;
    int in_w_start = out_w * stride_w - pad_w;
    int in_h_start = out_h * stride_h - pad_h;

    // Initialize accumulator
    float sum = 0.0f;

    // Loop over kernel and input channels
    for (int k_d = 0; k_d < kernel_depth; k_d++) {
        for (int k_w = 0; k_w < kernel_width; k_w++) {
            for (int k_h = 0; k_h < kernel_height; k_h++) {
                for (int ic = 0; ic < in_channels / groups; ic++) {
                    int in_d = in_d_start + k_d * dilation_d;
                    int in_w = in_w_start + k_w * dilation_w;
                    int in_h = in_h_start + k_h * dilation_h;

                    // Check bounds
                    if (in_d >= 0 && in_d < input_depth &&
                        in_w >= 0 && in_w < input_width &&
                        in_h >= 0 && in_h < input_height) {

                        // Calculate indices
                        int input_idx = batch_idx * (in_channels * input_depth * input_width * input_height) +
                                       (group_idx * (in_channels / groups) + ic) * (input_depth * input_width * input_height) +
                                       in_d * (input_width * input_height) + 
                                       in_w * input_height + 
                                       in_h;

                        int weight_idx = out_ch_idx * (in_channels / groups * kernel_depth * kernel_width * kernel_height) +
                                        ic * (kernel_depth * kernel_width * kernel_height) +
                                        k_d * (kernel_width * kernel_height) +
                                        k_w * kernel_height +
                                        k_h;

                        sum += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
                    }
                }
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * output_depth * output_width * output_height) +
                     out_ch_idx * (output_depth * output_width * output_height) +
                     out_d * (output_width * output_height) +
                     out_w * output_height +
                     out_h;

    output[output_idx] = __float2half(sum);
}

// Host wrapper function
extern "C" void launch_conv3d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_depth,
    int input_width,
    int input_height,
    int output_depth,
    int output_width,
    int output_height,
    int kernel_depth,
    int kernel_width,
    int kernel_height,
    int stride_d,
    int stride_w,
    int stride_h,
    int pad_d,
    int pad_w,
    int pad_h,
    int dilation_d,
    int dilation_w,
    int dilation_h,
    int groups
) {
    dim3 block_size(32, 32);  // Thread block size
    dim3 grid_size(batch_size, out_channels, output_depth);  // Grid size

    conv3d_kernel<<<grid_size, block_size>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_depth, input_width, input_height,
        output_depth, output_width, output_height,
        kernel_depth, kernel_width, kernel_height,
        stride_d, stride_w, stride_h,
        pad_d, pad_w, pad_h,
        dilation_d, dilation_w, dilation_h,
        groups
    );
}
"""

# Python model definition
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        # Initialize weights
        self.weight = torch.nn.Parameter(
            torch.randn(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size, dtype=torch.float16)
        )
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

        # Compile CUDA kernel
        self.conv3d_kernel = load_inline(
            name="conv3d_kernel",
            cpp_sources=cuda_source,
            cuda_sources=cuda_source,
            functions=["launch_conv3d"],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, depth, width, height = x.shape

        # Compute output dimensions
        output_depth = (depth + 2 * self.padding - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1
        output_width = (width + 2 * self.padding - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1
        output_height = (height + 2 * self.padding - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1

        # Allocate output tensor
        output = torch.empty(
            batch_size, self.out_channels, output_depth, output_width, output_height,
            dtype=torch.float16, device=x.device
        )

        # Launch CUDA kernel
        self.conv3d_kernel.launch_conv3d(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            depth,
            width,
            height,
            output_depth,
            output_width,
            output_height,
            self.kernel_size,
            self.kernel_size,
            self.kernel_size,
            self.stride,
            self.stride,
            self.stride,
            self.padding,
            self.padding,
            self.padding,
            self.dilation,
            self.dilation,
            self.dilation,
            self.groups
        )

        # Add bias if present
        if self.bias is not None:
            output = output + self.bias.view(1, -1, 1, 1, 1)

        return output

